import type { SourcedQuote } from './quoteTypes';

/**
 * Original reflections on distinct passages in public-domain primary works.
 * Neither language is a verbatim quotation or a copied modern translation.
 * The older editions linked below identify the underlying argument or episode;
 * the practical applications and wording belong to this collection.
 */
type Passage = [reference: string, tr: string, text: string, tags: string[]];

function readings(
  key: string,
  author: string,
  authorTr: string,
  book: string,
  bookTr: string,
  sourceUrl: string,
  rows: Passage[],
  islamic = false,
): SourcedQuote[] {
  return rows.map(([reference, tr, text, tags], index) => ({
    id: `philosophy-more-${key}-${String(index + 1).padStart(2, '0')}`,
    tr,
    text,
    source: `${author} — ${book}`,
    sourceTr: `${authorTr} — ${bookTr}`,
    sourceUrl,
    reference,
    category: 'philosophy',
    kind: 'adaptation',
    tags: [...(islamic ? ['islamic-philosophy'] : []), ...tags],
  }));
}

export const PHILOSOPHY_QUOTES_MORE: SourcedQuote[] = [
  ...readings('ghazali-confessions', 'Al-Ghazali', 'Gazâlî', 'Deliverance from Error (Field, 1909)', 'el-Munkız mine’d-Dalâl (Field, 1909)', 'https://www.gutenberg.org/files/58977/58977-h/58977-h.htm', [
    ['Search for Truth: inherited beliefs', 'Çocukluğundan beri duyduğun bir düşüncenin sende kök salması doğaldır. Şimdi ona kendi anlayışınla yaklaş; neye, hangi gerekçeyle inandığını araştırmak, inancına karşı değil onun sorumluluğunu üstlenmeye doğru bir adım olabilir.', 'An inherited belief can feel inseparable from you. Returning to its grounds with your own understanding can be an act of responsibility toward your faith and the life you build around it.', ['faith', 'self', 'courage']],
    ['The Subterfuges of the Sophists: the moving shadow', 'Gözünün önündeki gölge bile, anlık bakışın yakalayamadığı bir değişim taşıyabilir. İlk izlenimine biraz zaman ver; kendini ve dünyayı tek bir görüntünün içine hapsetmeden, yeniden bakmaya açık ol.', 'Even a shadow changes while a glance calls it still. Give an impression time before allowing it to settle your understanding of yourself or the world.', ['self', 'perspective', 'patience']],
    ['Philosophy: understanding a discipline before refuting it', 'Karşı çıktığın fikri yalnız zayıf yanından tanıyorsan, henüz bütününü görmemiş olabilirsin. İtirazını güçlendirmek için önce onu ciddi biçimde öğren; anlamaya ayırdığın emek, kendi düşüncene de sağlamlık kazandırsın.', 'An argument deserves to be understood at its strongest before you challenge it. Learning its discipline carefully can make your disagreement more responsible and your own position better grounded.', ['humility', 'learning', 'reason']],
    ['Divisions of the Philosophic Sciences: mathematics and religious belief', 'İnancını koruma isteğin, doğru bir hesabı ya da açık bir kanıtı reddetmeyi gerektirmez. Hangi sorunun hangi bilgiyle yanıtlandığını ayırt etmek, zihninde gereksiz bir çatışmanın büyümesini önleyebilir.', 'You need not reject a sound calculation to protect your faith. Distinguishing the questions different disciplines answer can prevent an unnecessary conflict from taking root in your mind.', ['faith', 'reason', 'discernment']],
    ['Divisions of the Philosophic Sciences: truth and the identity of its speaker', 'Bir düşünceyi yalnız söyleyen kişiye duyduğun yakınlıkla tartma. Sevmediğin birinden gelen doğruyu da inceleyebilmek, benliğinin taraf tutma isteğinden bir adım uzaklaşıp hakikate daha adil yaklaşmana yardım eder.', 'Your feelings about a speaker need not decide the worth of an idea. Examining a truth from someone you dislike gives understanding a chance beyond personal allegiance.', ['ego', 'truth', 'humility']],
    ['The Aim of Scholastic Theology: different remedies for different seekers', 'Sana iyi gelmeyen bir düşünme yolu, başkasının arayışına gerçekten yardımcı olmuş olabilir. Kendi tecrübeni herkesin ölçüsü yapmadan anlat; farklı ihtiyaçları kabul etmek, kendi yolunu seçme hakkını da korur.', 'A path that did not help your inquiry may have helped someone else. Describe your experience without turning it into a universal measure for every seeker.', ['self', 'difference', 'compassion']],
    ['Sufism: examining the motive behind teaching and reputation', 'Yaptığın işin değeri kadar, seni ona bağlayan niyete de bak. Gazâlî’nin kendi şöhret arzusunu sorgulaması, dışarıdan başarılı görünürken içeride yönünü yeniden seçebileceğini hatırlatan cesur bir duraklamadır.', 'Consider the motive that keeps you in a respected role. Al-Ghazali’s scrutiny of his own ambition offers a pause in which outward success can be reconsidered from within.', ['ego', 'intention', 'courage']],
    ['Sufism: hesitation between leaving Baghdad and worldly attachment', 'Bir değişimi istemekle ona hazır hissetmek aynı anda gelmeyebilir. Gazâlî’nin uzun tereddüdünü düşün; kararsızlığını hemen karakter kusuru saymadan, seni tutan bağı dürüstçe tanımaya ve seçimini olgunlaştırmaya çalış.', 'Wanting a change and feeling ready can arrive at different times. Al-Ghazali’s prolonged hesitation invites an honest look at attachment without reducing uncertainty to a defect of character.', ['fear', 'courage', 'self']],
  ], true),
  ...readings('ghazali-ihya', 'Al-Ghazali', 'Gazâlî', 'Ihya Ulum al-Din (Nawab Ali selections, 1921)', 'İhyâ (Nawab Ali seçkisi, 1921)', 'https://www.gutenberg.org/files/73140/73140-h/73140-h.htm', [
    ['I, The Nature of Man: knowledge, appetite and will', 'İlk isteğin, verebileceğin tek karar değildir. Gazâlî’nin irade anlayışında sonuçları düşünerek iyiyi seçmeye yer vardır; bugün güçlü bir dürtünün yanında, neyi gerçekten onayladığını da kendine sor.', 'Your first impulse is not your only possible decision. Al-Ghazali distinguishes appetite from a will informed by consequences; ask what you can thoughtfully endorse alongside what you immediately want.', ['will', 'self', 'action']],
    ['I, The Nature of Man: the body as the soul’s vehicle', 'İç dünyanı geliştirmek isterken bedenini önemsiz bir yük sayma. Gazâlî’nin yolculuk benzetmesinde taşıtın da bakıma ihtiyacı vardır; öğrenmeye ve ibadete ayırdığın özen, günlük bakımına da uzanabilir.', 'Inner development need not make bodily care seem trivial. In Al-Ghazali’s journey metaphor the vehicle matters too; let everyday care support the attention you bring to learning and worship.', ['self', 'care', 'balance']],
    ['III, Pride and Vanity: comparison and the claim to superiority', 'Kendinde bir iyilik görmen, başkasını aşağıda görmeni gerektirmez. Gazâlî’nin kibir çözümlemesinde sorun, değeri üstünlük yarışına çevirmektir; yeteneğini fark ederken karşındakinin eşit insanlık değerine de yer bırak.', 'Recognizing something good in yourself need not place another person beneath you. Al-Ghazali’s account of pride questions the ranking impulse that turns a gift into a claim to superiority.', ['ego', 'dignity', 'humility']],
    ['III, Pride and Vanity: the inability to receive advice', 'Bir uyarı duyduğunda hemen itibarını savunmak isteyebilirsin. Önce içinde işe yarayan bir şey olup olmadığını dinle; kendini her an haklı göstermek zorunda kalmamak, benliğine beklemediğin bir ferahlık verebilir.', 'A correction can make you rush to protect your standing. Listen for what it offers before defending yourself; freedom from constant self-justification leaves room to grow.', ['ego', 'learning', 'courage']],
    ['III, Pride and Vanity: learning magnifies the learner’s disposition', 'Bilgi çoğaldıkça kusurlarının kendiliğinden azalacağını varsayma. Gazâlî, öğrenmenin kibri de besleyebileceğini hatırlatır; her yeni becerinin yanında, onu insanlara nasıl davrandığında gösterdiğini de dikkatle gözden geçir.', 'More knowledge does not automatically mean fewer faults. Al-Ghazali warns that learning can nourish pride; notice how each new ability changes the way you meet other people.', ['ego', 'knowledge', 'integrity']],
    ['III, Pride and Vanity: the pride of the religious devotee', 'İbadetinin sende bıraktığı izi, başkasına baktığın yerde de ara. Daha çok küçümsemeye başladıysan durup niyetini yokla; manevî emek, insanları mahkûm etme yetkisi aldığın bir mertebeye dönüşmesin.', 'Look for the effects of devotion in your regard for others. If contempt is growing, examine the motive; spiritual practice need not become a claim to judge everyone beneath you.', ['faith', 'ego', 'compassion']],
    ['III, Pride and Vanity: pride in ancestry', 'Ailenden gelen bir adı, kendi emeğinin yerine koymak zorunda değilsin. Geçmişinle bağını korurken bugünkü davranışına da sahip çık; sana bırakılan itibar, şimdi nasıl yaşadığının sorusunu senin adına cevaplamaz.', 'An inherited name cannot do your living for you. Honor your connection with the past while taking responsibility for conduct that belongs to you today.', ['ego', 'responsibility', 'identity']],
    ['IV, Friendship and Sincerity: wisdom joined with good character', 'Bir dostun yalnızca zeki olması, yanında güvende hissedeceğin anlamına gelmeyebilir. Yakınlık kurarken bilgisiyle birlikte huyuna da bak; aklın sıcak bir karakterle buluşması, arkadaşlığa daha sağlam bir zemin verir.', 'Intelligence alone does not make a trustworthy companion. Notice character as well as insight; friendship needs a way of treating people that knowledge by itself cannot supply.', ['friendship', 'discernment', 'trust']],
    ['IV, Friendship and Sincerity: ideals and practical friendship', 'Kusursuz dostu beklerken kurulabilecek bütün bağlardan vazgeçme. Gazâlî, ideal tasvirlerin yanında gerçek hayatın şartlarını da düşünür; makul bir beklentiyle yaklaşmak, insanların verebildiği iyiliği görmeni ve karşılık vermeni kolaylaştırabilir.', 'Waiting for a flawless friend can leave every possible connection unopened. Al-Ghazali tempers ideals with practical circumstances; reasonable expectations make the good someone can offer easier to recognize.', ['connection', 'hope', 'acceptance']],
    ['IV, Friendship and Sincerity: mixed motives and their effects on the heart', 'Bir davranışın ardında hem iyilik hem görünme isteği bulunabilir. Bunu fark etmek, bütün emeğini silmeni gerektirmez; bugün hangi niyeti beslediğine bakıp bir sonraki davranışını daha içten seçebilirsin.', 'Care and a wish for recognition can share one action. Noticing the mixture need not erase your effort; consider which motive your next choice will strengthen.', ['ego', 'intention', 'renewal']],
    ['V, The Nature of Love: inner beauty and qualities of character', 'Güzelliği yalnız görünen biçime bağladığında, adaletin ve cömertliğin çekiciliği gözden kaçabilir. Bir insanda hayran olduğun niteliği adlandır; kendi hayatında o niteliğe nasıl yer açabileceğini de düşün.', 'Beauty can be encountered in justice and generosity as well as appearance. Name a quality you admire in someone and consider what giving it room in your own life would involve.', ['self', 'beauty', 'values']],
    ['VII, The Love of God and its Signs: loving the Creator’s creatures', 'Allah’a duyduğun sevginin, yarattıklarına davranışında da karşılık bulmasına izin ver. Bir insanın yanlışını onaylamadan insanlığını gözetebilirsin; merhametle sınır koymak, kalbindeki bağlılığı gündelik hayatta daha görünür kılabilir.', 'Let love of God find expression in your care for creation. You can reject a harmful action without erasing the person’s humanity; compassion can accompany a clear boundary.', ['faith', 'compassion', 'boundaries']],
  ], true),
  ...readings('tufayl', 'Ibn Tufayl', 'İbn Tufeyl', 'Hayy ibn Yaqzan (Ockley, 1708)', 'Hayy bin Yakzan (Ockley, 1708)', 'https://www.gutenberg.org/cache/epub/16831/pg16831-images.html', [
    ['§§12–14: bodily comparison and making a covering', 'Başkalarında gördüğün imkân sende yoksa, bütün gücünün de yok olduğunu düşünme. Hayy’ın kendi araçlarını yapmasını hatırla; eksikliğini kabul ederek, elindeki beceriyle farklı bir çözüm aramaya başlayabilirsin.', 'Missing an advantage others possess does not mean having no resources. Hayy’s improvised tools suggest a beginning: acknowledge the difference and explore what your own abilities can make possible.', ['self', 'courage', 'resourcefulness']],
    ['§15: improving an inadequate covering', 'İlk bulduğun çözümün sürekli onarım istemesi, arayışının boşa gittiğini göstermez. Hayy gibi kullanımın öğrettiklerine bak; aynı soruna daha uygun bir düzen bulmak, başladığın yoldan öğrenerek ilerlemenin parçasıdır.', 'A first solution that keeps needing repair still teaches something. Hayy revises what he makes through use; improvement can grow from the inconvenience you have learned to describe.', ['action', 'learning', 'patience']],
    ['§§16–22: the doe’s death and inquiry into life', 'Sevdiğin bir varlığın kaybı, dünyayı eskisi gibi görmeni zorlaştırabilir. Hayy’ın kederinden doğan soruları düşün; yasın hemen cevap bulmasını beklemeden, anlam arayışının yanında nazikçe durmasına izin ver.', 'Loss can disturb your whole understanding of life. Hayy’s questions arise within grief; an inquiry into meaning can accompany sorrow without requiring an immediate answer or a quick recovery.', ['existence', 'grief', 'meaning']],
    ['§23: learning burial from the raven', 'Öğretmenin her zaman beklediğin yerde durmaz. Hayy’ın kuzgundan öğrenmesini hatırla; kendi bilgisinin dışındaki bir davranışa dikkat kesilen insan, en yalnız zamanında bile dünyadan yeni bir şey alabilir.', 'A teacher need not arrive in a familiar form. Hayy learns by watching a raven; attention to a life unlike your own can keep learning open even in solitude.', ['humility', 'attention', 'learning']],
    ['§24: approaching the unfamiliar fire', 'Yeni bir şey korkuttuğunda, korkunu yok saymak zorunda değilsin. Hayy’ın ateşe uzaktan bakıp yavaşça yaklaşması gibi, önce tehlikeyi tanı; güvenli ve ölçülü bir adım merakına yeniden alan açabilir.', 'Fear of something unfamiliar need not be dismissed. Like Hayy first observing fire from a distance, understand the danger and choose a measured, safe step toward what you want to learn.', ['fear', 'courage', 'action']],
    ['§30: practical crafts accumulated by the third seven-year period', 'Bir hayatı taşıyan beceriler tek bir parlak buluşla oluşmayabilir. Hayy’ın barınaktan ip yapımına uzanan emeği gibi, küçük ihtiyaçları çözmeyi öğrenmek de zamanla kendine dayanabileceğin somut bir birikim kurar.', 'Skills that sustain a life may accumulate through ordinary needs. Hayy’s shelter and cord-making show how practical problems, worked through over time, can build a tangible basis for self-reliance.', ['confidence', 'practice', 'patience']],
    ['§33: the many members and the unity of a living being', 'Kendini yalnız bir özelliğinle tanımladığında, hayatının geri kalanı daralabilir. Hayy’ın çokluk içinde bütünlük arayışını düşün; düşüncelerin, bedenin ve uğraşların arasındaki ilişkilere bakarak kendine daha geniş bir yer aç.', 'One trait need not stand for your entire existence. Hayy looks for unity among many parts; consider the relationships among your thoughts, body, and pursuits when reflecting on who you are.', ['self', 'identity', 'existence']],
    ['§§35–37: shared characteristics of animals and plants', 'Canlılar arasındaki ayrılıklara bakarken ortak ihtiyaçları da fark et. Hayy’ın gözlemlerinde beslenme ve büyüme pek çok biçimde sürer; kendini dünyanın dışında görmeden, yaşamla paylaştığın bağları düşünmeye zaman ayır.', 'Difference among living things can coexist with shared needs. Hayy notices nourishment and growth across forms of life; consider the connections that place your existence within a wider living world.', ['existence', 'connection', 'care']],
    ['§41: turning from an abstract difficulty to examining water', 'Bir soru zihninde fazla soyutlaştığında, onu görebileceğin bir örneğe yaklaştır. Hayy’ın suyu incelemeye yönelmesi gibi, elindeki somut durumdan başlamak düşünceni küçültmez; araştırmana tutunabileceğin belirli bir yer verir.', 'When a question becomes too abstract, bring it near an example you can examine. Hayy’s attention turns to water; something concrete can provide a foothold for a difficult inquiry.', ['action', 'reason', 'clarity']],
    ['§§49–50: looking beyond nearby bodies to the heavens', 'Uzun süre aynı çerçevede düşünmek, sorunun sınırlarını dünyanın sınırları gibi gösterebilir. Hayy’ın bakışını göğe çevirmesi gibi, bazen yeni bir ölçek seçmek, zihninde sıkışan düşünceye başka bir hareket alanı açar.', 'A familiar frame can begin to feel like the limit of reality. Hayy’s inquiry turns toward the heavens; changing the scale of a question may give thought another direction.', ['perspective', 'hope', 'reason']],
    ['§§57–61: the ordered world and contemplation of its source', 'Hayy için varlıktaki düzen, bakışın durduğu son nokta değil, yaratıcıya yönelen düşüncenin başlangıcıdır. Sen de hayret ettiğin bir şeyi geçiştirmeden, onun sende uyandırdığı anlam sorusuna biraz zaman verebilirsin.', 'For Hayy, the world’s order opens contemplation of its source. Stay for a moment with something that awakens wonder and the question of meaning it brings into your life.', ['faith', 'existence', 'wonder']],
    ['§62: asking which faculty makes knowledge possible', 'Bir sonuca vardığında, onu nasıl bildiğini de sor. Hayy’ın kendi bilme gücüne dönmesi gibi, gözlemle düşünceyi ayırt etmek sana yalnız cevap değil, zihninin işleyişine dair daha açık bir anlayış kazandırabilir.', 'After reaching a conclusion, ask how you reached it. Hayy examines his own ways of knowing; distinguishing observation from reflection can reveal something about the mind doing the inquiry.', ['self', 'reason', 'awareness']],
    ['§§66, 74–75: contemplation and the needs of bodily life', 'Derin bir şeye odaklanmak isterken gündelik ihtiyaçların araya girmesi, arayışını değersiz kılmaz. Hayy bile bedeninin ihtiyaçlarıyla karşılaşır; anlamlı bir uğraşı sürdürebilmek için hayatının temel bakımına da yer aç.', 'Everyday needs do not invalidate an inward search. Even Hayy encounters bodily demands; sustaining a meaningful pursuit requires room for the ordinary conditions that allow it to continue.', ['self', 'care', 'meaning']],
    ['§76: nourishment and care for the continuation of living things', 'Bir ihtiyacını karşılarken yalnız sana sağladığı yararı düşünmeyebilirsin. Hayy’ın canlıların devamını gözeten arayışı, tüketimin ardındaki hayatı fark etmeye çağırır; bugün aldığın şeyin nasıl bir ilişki kurduğunu da düşün.', 'Meeting a need can include concern for the life that supplies it. Hayy considers the continuation of living things; notice the relationship your everyday consumption establishes with the wider world.', ['care', 'responsibility', 'existence']],
    ['§79: freeing plants, helping animals and opening watercourses', 'Manevî bir arayış, çevrendeki küçük ihtiyaçlardan uzaklaşmak zorunda değildir. Hayy’ın su yolunu açması ve zarar gören canlıya yardım etmesi gibi, bugün somut bir engeli kaldırmak da içindeki yönelişe karşılık olabilir.', 'An inward search can reach outward into practical care. Hayy clears watercourses and helps vulnerable creatures; removing a small obstacle around you can give an inner commitment visible expression.', ['faith', 'action', 'compassion']],
    ['§80: cleanliness as part of deliberate practice', 'Kendine gösterdiğin özenin anlamlı sayılması için büyük bir değişime dönüşmesi gerekmez. Hayy’ın gündelik temizliği düşün; bedenine ve yaşadığın yere dikkat etmek, iç düzen arayışının sessiz bir parçası olabilir.', 'Care for yourself need not become a dramatic transformation to matter. Hayy makes cleanliness part of practice; attention to body and surroundings can quietly accompany a search for inward order.', ['care', 'self', 'action']],
    ['§100: Asal’s solitude and Salaman’s social inclination', 'Bazı insanlar düşünmek için yalnızlığı, bazıları birlikte yaşamayı seçer. Asâl ile Salâmân’ın ayrılığını düşün; sana iyi gelen düzeni ararken, herkesin aynı yoldan güç bulmasını beklemek zorunda değilsin.', 'Some people seek understanding in solitude, others in shared life. Asal and Salaman choose differently; finding your own sustaining arrangement need not require everyone to thrive in the same way.', ['self', 'difference', 'belonging']],
    ['§105: Hayy notices Asal’s fear and tries to reassure him', 'Birinin senden çekindiğini fark ettiğinde, hemen kendini anlatmaya yüklenme. Hayy’ın önce korkuyu yatıştırmaya çalışması gibi, güven kuracak bir tavır seç; anlaşılmanın yolu bazen ilk olarak karşıdakine alan vermekten geçer.', 'When someone seems afraid of you, explanation may not be the first need. Hayy tries to reassure Asal; a considerate manner can make space for understanding before words do.', ['fear', 'compassion', 'connection']],
    ['§108: learning names through shared objects and companionship', 'İletişim bir anda kurulmadığında, aradaki boşluğu başarısızlık sayma. Asâl’ın Hayy’a nesneleri göstererek dil öğretmesi gibi, ortak bir deneyimden başlamak, kelimelerin zamanla güven içinde yerleşmesine yardımcı olabilir.', 'A connection need not be complete at the first encounter. Asal teaches Hayy through shared objects; a common experience can give unfamiliar words somewhere to take root.', ['patience', 'learning', 'connection']],
    ['§§115–118: unsuccessful teaching and returning to Salaman', 'İyi niyetle anlattığın şeyin herkese ulaşmaması, insanları daha fazla sıkıştırman gerektiğini göstermez. Hayy’ın deneyimini düşün; anlatımının sınırlarını görüp yaklaşımını değiştirmek de bir düşünürün öğrenmeye devam etmesidir.', 'A sincere message may still fail to reach its audience. Hayy’s encounter with society asks the teacher to recognize limits; reconsidering an approach can be another form of learning.', ['ego', 'humility', 'communication']],
  ], true),
  ...readings('rushd', 'Ibn Rushd', 'İbn Rüşd', 'The Decisive Discourse (Jamil ur Rehman, 1921)', 'Faslü’l-Makāl (Jamil ur Rehman, 1921)', 'https://oll-resources.s3.us-east-2.amazonaws.com/oll3/store/titles/77/Averroes_0560_EBk_v6.0.pdf', [
    ['Opening argument: studying beings as signs of their Maker', 'Varlığı anlamaya çalışırken inancını kapının dışında bırakmak zorunda değilsin. İbn Rüşd’ün yaklaşımında yaratılmışları incelemek, yaratıcıya ilişkin düşünceyi derinleştirebilir; merakına ciddi ve özenli bir çalışma alanı aç.', 'Inquiry into existence need not leave faith outside the door. Ibn Rushd treats examination of created things as a path toward understanding their Maker; give curiosity a careful discipline.', ['faith', 'reason', 'curiosity']],
    ['The instrument of reasoning: learning the kinds of inference', 'Doğru sonuca ulaşma isteğin kadar, oraya hangi adımlarla gittiğin de önemlidir. İbn Rüşd’ün akıl yürütme araçlarına verdiği değeri düşün; gerekçelerini sıraya koymak, zihnindeki güveni daha sağlam bir temele bağlayabilir.', 'Wanting a true conclusion includes caring about the route toward it. Ibn Rushd emphasizes the instruments of reasoning; laying out your grounds can give confidence something more dependable to rest on.', ['reason', 'confidence', 'clarity']],
    ['Predecessors: benefiting from earlier work regardless of religious affiliation', 'Senden farklı bir gelenekten gelen insanın emeği de öğrenmene katkı sunabilir. İbn Rüşd’ün eski düşünürlere yaklaşımını hatırla; yararlı bir bilgiyi kaynağının kimliği yüzünden baştan dışlamadan dikkatle incele.', 'Work from another tradition can contribute to your understanding. Ibn Rushd welcomes the labor of earlier thinkers; consider a useful insight without dismissing it merely because of its origin.', ['humility', 'learning', 'openness']],
    ['Cumulative knowledge: one person cannot reconstruct astronomy alone', 'Her şeyi tek başına yeniden bulman gerekmiyor. İbn Rüşd’ün astronomi örneğinde olduğu gibi, büyük bir arayış önceki emeklere dayanır; yardım almak, kendi katkını mümkün kılan dürüst bir başlangıç olabilir.', 'You need not rediscover everything alone. Ibn Rushd’s example of astronomy shows how inquiry depends on earlier work; accepting that inheritance can make a contribution of your own possible.', ['ego', 'support', 'action']],
    ['Reading predecessors: accepting the sound and identifying the unsound', 'Bir düşünürü önemsemek, söylediği her şeyi kabul etmek değildir. Sağlam bulduğun yanı alırken sorunlu gördüğün kısmı gerekçesiyle ayırabilirsin; saygılı bir okuma, kendi yargını başkasına bütünüyle teslim etmeyi gerektirmez.', 'Respect for a thinker does not require agreement with every claim. Receive what is sound and identify what fails with reasons; careful reading can combine gratitude with independent judgment.', ['self', 'discernment', 'integrity']],
    ['Accidental harm: the thirsty person and the water', 'Bir aracın yanlış kullanımla zarar vermesi, bütün yararını ortadan kaldırmaz. İbn Rüşd’ün su benzetmesini düşün; korkunun seni bütünüyle vazgeçirmesinden önce, kullanma koşullarını ve gerekli hazırlığı ayırt etmeye çalış.', 'Misuse does not cancel every benefit of a practice. Ibn Rushd’s water analogy invites a distinction between a thing and the conditions of using it; preparation may answer fear more usefully than rejection.', ['fear', 'courage', 'discernment']],
    ['Truth and the Law: truth supports rather than contradicts truth', 'İnandığınla öğrendiğin çatışıyor göründüğünde, hemen birini susturmak zorunda değilsin. İbn Rüşd’ün hakikat anlayışını düşün; hem kanıtı hem yorumunu yeniden incelemek, acele bir karşıtlıktan daha verimli bir arayış başlatabilir.', 'When belief and discovery seem opposed, neither needs to be silenced immediately. Ibn Rushd’s account of truth encourages another examination of both the evidence and the interpretation.', ['faith', 'reason', 'patience']],
    ['Interpretation: figurative meaning and the conventions of Arabic', 'Bir metindeki mecazı kendi isteğine göre doldurmadan önce, dilin imkânlarını ve bağlamını öğren. Anlam arayışı özgürce soru sormayı içerirken, yorumunun hangi dayanaklarla kurulduğunu gösterecek bir özen de ister.', 'Before filling a metaphor with your preferred meaning, attend to language and context. An inquiry can be open while remaining responsible for the grounds of its interpretation.', ['reason', 'responsibility', 'meaning']],
    ['Mistakes of qualified interpreters: the analogy with judicial judgment', 'Ciddi bir araştırmada yanılmak, bütün emeğin değersizleştiği anlamına gelmeyebilir. İbn Rüşd’ün ehil yorumcunun hatasına yaklaşımı, gerekli hazırlığı yaparak düşünmeye ve bir yanlış ortaya çıktığında onu dürüstçe düzeltmeye alan açar.', 'An error in serious inquiry need not cancel the work. Ibn Rushd distinguishes the qualified interpreter’s mistake from careless judgment; preparation can coexist with a willingness to correct yourself.', ['fear', 'courage', 'learning']],
    ['Different methods of assent: demonstrative, dialectical and rhetorical', 'Sana açık görünen bir gerekçe, başka birine aynı kapıyı açmayabilir. İbn Rüşd’ün farklı anlama yollarını düşün; insanı küçümsemek yerine, konuşmanın ona nasıl ulaşabileceğini araştırmak da düşüncenin sorumluluğudur.', 'A reason that convinces you may not reach another person in the same way. Ibn Rushd distinguishes ways of understanding; consider the listener instead of treating difference as inferiority.', ['ego', 'communication', 'understanding']],
  ], true),
  ...readings('spinoza', 'Baruch Spinoza', 'Baruch Spinoza', 'Ethics (Elwes, 1883)', 'Etika (Elwes, 1883)', 'https://www.gutenberg.org/files/3800/3800-h/3800-h.htm', [
    ['III, propositions 6–7: the endeavour to persist in being', 'Varlığını sürdürme çabanı yalnız büyük başarılarla ölçme. Spinoza’nın kendini koruma düşüncesini hatırla; bugün hayatını ayakta tutan bir işi yapmak, görünür bir zafer olmasa da kendi varlığına sahip çıkmanın anlamlı bir biçimidir.', 'Your effort to continue need not be measured only by major achievements. Through Spinoza’s account of persistence, an ordinary act that sustains your life can carry significance without looking like a victory.', ['self', 'existence', 'action']],
    ['III, proposition 9, scholium: desire and judgments of goodness', 'Bir şeyi istemenle onu iyi bulman birbirine karışabilir. Arzunun kararına nasıl yön verdiğini fark et; benliğini tanımak, her güçlü isteği sorgusuzca doğru bir yolun işareti saymamayı da içerir.', 'Wanting something and judging it good can become intertwined. Notice desire’s part in your decision; knowing yourself includes questioning whether intensity alone makes an aim worth pursuing.', ['ego', 'self', 'desire']],
    ['III, proposition 11, scholium: joy and increased power of acting', 'Seni sevindiren şeyin hayatında nasıl bir hareket alanı açtığına bak. Spinoza’nın sevinç anlayışı, yalnız hoş bir anı değil, düşünmeye ve yaşamaya daha geniş katılabildiğin değişimi de fark etmeye çağırır.', 'Notice what a joy makes possible in your life. Spinoza understands joy through an increase in the power to act; a welcome feeling can invite reflection on what it opens.', ['self', 'joy', 'possibility']],
    ['III, proposition 14: emotions associated through simultaneous experience', 'Bir yerin ya da sesin sende uyandırdığı duygu, geçmişte onunla birlikte yaşadığın bir andan gelebilir. Bugünkü tepkinin bütününü bugünkü olaya yüklemeden, hafızanın kurduğu bağı merakla inceleyebilirsin.', 'A place or sound may carry a feeling from an earlier encounter. Before assigning your whole response to the present situation, consider the association memory might be bringing with it.', ['self', 'memory', 'awareness']],
    ['III, proposition 18: images of past and future affect the present', 'Henüz yaşanmamış bir olayı düşünürken, onun duygusu şimdiki anına yerleşebilir. Gelecekle ilgili korkunu küçümsemeden, düşündüğün görüntüyle şu anda önünde duran gerçek durumu birbirinden ayırmak için biraz durakla.', 'An imagined future can bring a real feeling into the present. Respect the fear while distinguishing the scene in your mind from the situation actually before you now.', ['fear', 'self', 'presence']],
    ['III, proposition 27: imitation of the emotions', 'İçindeki duygu, yalnız kendi başına yaşadıklarından oluşmayabilir. Başkasının sevincine veya sıkıntısına eşlik ederken sen de etkilenirsin; bu bağı fark etmek, kendini anlamana ve ilişkilerine daha bilinçli yaklaşmana yardım edebilir.', 'Your feelings can take shape through another person’s experience too. Recognizing this participation may help you understand yourself while approaching companionship with greater awareness.', ['self', 'connection', 'empathy']],
    ['III, proposition 32: envy where possession is imagined as exclusive', 'Bir başkasının başarısını, sana ayrılabilecek bütün yerin azalması gibi görmeye başladığında dur. Her iyilik paylaşılmaz olmak zorunda değildir; rekabetin benliğinde hangi kıtlık düşüncesini büyüttüğünü fark etmeye çalış.', 'Pause when another person’s success seems to remove all room for yours. Not every good must be exclusive; consider the picture of scarcity that is shaping your comparison.', ['ego', 'envy', 'perspective']],
    ['III, proposition 51: people and times differ in their responses', 'Dün seni zorlayan bir şeyin bugün daha kolay gelmesi, geçmişteki hâlinin sahte olduğu anlamına gelmez. Aynı insan zamanla farklı etkilenebilir; kendini tek bir tepkinin içinde dondurmadan değişimine dikkat et.', 'If something feels easier today, yesterday’s difficulty was not therefore unreal. A person can respond differently across time; leave room for change in the story you tell about yourself.', ['self', 'identity', 'hope']],
    ['III, proposition 53: contemplating one’s own power of acting', 'Yapabildiğin bir şeyi fark etmek için başkasının seni övmesini beklemek zorunda değilsin. Bugün kendi emeğinden doğan bir davranışı adlandır; kendini görmen, gösterişe dönüşmeden de sana içten bir sevinç verebilir.', 'You need not wait for praise to recognize an ability in action. Name something your effort made possible today; acknowledgment can bring quiet enjoyment without becoming a performance.', ['self', 'confidence', 'agency']],
    ['IV, proposition 18, scholium: rational self-interest and mutual usefulness', 'Kendi iyiliğini gözetmekle başkasına yararlı olmak her zaman karşıt değildir. Spinoza’nın ortak yarar düşüncesi gibi, birlikte güçlenebileceğiniz bir ilişki ara; benliğini korumak, insanlardan bütünüyle kopmanı gerektirmeyebilir.', 'Care for your own good can meet care for another’s. Spinoza’s account of mutual usefulness invites relationships that strengthen both people, rather than treating self-preservation as necessary isolation.', ['self', 'cooperation', 'belonging']],
    ['IV, proposition 37: the good sought for oneself and for others', 'Kendin için değerli bulduğun anlayışın başkalarına da ulaşmasını isteyebilirsin. Bir şeyi paylaşmak, onun senin hayatındaki yerini mutlaka küçültmez; bazı iyilikler, birlikte aranabildiklerinde daha geniş bir anlam kazanır.', 'An understanding you value for yourself can also be something you wish for others. Sharing a good need not diminish its place in your own life.', ['ego', 'generosity', 'meaning']],
    ['IV, proposition 46: answering hatred through generosity', 'Karşındaki öfkenin seni aynı biçimde yönetmesine izin vermemek mümkündür. Sınırını korurken aşağılamaya başvurmadan cevap vermeyi dene; bir çatışmada tutumunu seçebilmek, benliğinin bütününü o çatışmaya teslim etmemektir.', 'You can protect a boundary without copying another person’s hostility. A response free of humiliation leaves some authorship of your conduct with you, even within a difficult conflict.', ['self', 'courage', 'boundaries']],
    ['IV, proposition 52: self-approval grounded in reason', 'Kendine güvenini yalnız alkışa bağladığında, sessizlik bile onu sarsabilir. Neyi neden yaptığını anlayarak duyduğun memnuniyete de yer aç; kendi değerlendirmene dayanan bir zemin, dışarıdaki seslerden ayrı olarak kurulabilir.', 'Confidence tied only to applause can be unsettled by silence. Make room for satisfaction grounded in understanding your conduct; your own assessment can provide another place to stand.', ['ego', 'confidence', 'reason']],
    ['IV, proposition 57: pride and the preference for flatterers', 'Seni yalnız onaylayan insanlarla çevrelendiğinde, kendin hakkındaki görüntün daralabilir. Dürüst bir dostun farklı görüşüne yer aç; benliğini korumak için her eleştiriyi düşmanlık saymak zorunda kalmadığın ilişkiler de kurulabilir.', 'A circle of constant approval can narrow your view of yourself. Give an honest companion room to differ; a relationship need not protect your image at the expense of understanding.', ['ego', 'friendship', 'honesty']],
    ['IV, proposition 63 and corollary: seeking a good instead of acting only from fear', 'Korkun yanındayken de neyi değerli bulduğunu sorabilirsin. Yalnız kaçınmak istediğin sonuca odaklanmak yerine, korumak ya da kurmak istediğin iyiliği adlandır; sonraki küçük adımını o değere bağlamayı dene.', 'Even with fear present, ask what you value. Alongside the outcome you want to avoid, name the good you want to protect or create and connect a small step to it.', ['fear', 'courage', 'values']],
    ['IV, proposition 67: the free person’s attention to life', 'Hayatın sonlu olduğunu bilmek, bütün düşünceni sona ayırmanı gerektirmez. Spinoza’nın yaşam üzerine düşünme çağrısını hatırla; bugün nasıl yaşamak istediğin sorusu, varoluşuna katılabileceğin somut bir kapı açabilir.', 'Knowing that life ends need not occupy every thought with its ending. Spinoza turns attention toward living; asking how you want to live today can open a practical point of participation.', ['existence', 'meaning', 'action']],
    ['IV, proposition 69: courage in avoiding as well as overcoming danger', 'Cesaret her tehlikenin içine girmek değildir. Bazen geri çekilmek ya da daha güvenli bir yol seçmek aynı kararlılığı ister; korkunu dinleyip koşulları değerlendirmek, yapabileceklerinden vazgeçtiğin anlamına gelmez.', 'Courage does not require entering every danger. Withdrawing or choosing a safer route may demand equal firmness; attending to fear and circumstances need not mean abandoning what you can do.', ['fear', 'courage', 'judgment']],
    ['V, proposition 3: understanding an emotion more clearly', 'Duygunu yalnız susturulacak bir engel gibi görmeden, içinde hangi düşüncenin bulunduğunu araştır. Onu anlamaya çalışmak her şeyi bir anda çözmeyebilir; yine de kendinle kurduğun ilişkiye biraz açıklık katabilir.', 'Instead of treating a feeling only as an obstacle, explore the thought within it. Understanding need not resolve everything immediately to make your relationship with yourself a little clearer.', ['self', 'awareness', 'compassion']],
    ['V, proposition 10, scholium: preparing principles when not overwhelmed', 'Sakin bir anında, zor bir karşılaşmada nasıl davranmak istediğini düşün. Küçük bir hazırlık korkuyu tamamen kaldırmayabilir; fakat duygu yükseldiğinde, önceden benimsediğin bir ilkeyi hatırlamana yardımcı olacak bir iz bırakabilir.', 'During a calmer moment, consider how you want to act in difficulty. Preparation need not remove fear completely to leave you a principle worth remembering when emotion rises.', ['fear', 'courage', 'preparation']],
    ['V, proposition 42: blessedness and virtue rather than an external prize', 'İyi yaşamanın değerini yalnız gelecekte verilecek bir ödüle erteleme. Spinoza’nın son önermesi gibi, anlayarak ve değerlerine bağlı yaşayabildiğin anın kendisinde de bir sevinç bulunabileceğini düşünmeye yer aç.', 'The value of living well need not be postponed to a later prize. Spinoza’s final proposition locates fulfillment within virtue itself; consider the joy available in an understood and deliberate life.', ['self', 'meaning', 'joy']],
  ]),
  ...readings('descartes', 'René Descartes', 'René Descartes', 'Discourse on Method (1650 English edition)', 'Yöntem Üzerine Konuşma (1650 İngilizce baskı)', 'https://www.gutenberg.org/cache/epub/25830/pg25830-images.html', [
    ['I: travel and the diversity of customs', 'Kendi çevrende alışılmış olanı, insan olmanın tek yolu sayma. Başka yaşayışlarla karşılaşmak, fark etmeden taşıdığın kabulleri görünür kılabilir; bu karşılaşmadan kendini kaybetmeden, daha bilinçli bir seçimle dönebilirsin.', 'What is customary around you need not be the only way to live. Encountering other ways can reveal assumptions you have carried unnoticed and let you return with a more deliberate choice.', ['self', 'identity', 'perspective']],
    ['I: proceeding slowly on a sound route', 'Hızlı görünmek uğruna yönünü kaybetmen gerekmiyor. Descartes’ın yavaş fakat doğru ilerleyen yolcu benzetmesini düşün; bugün anladığın bir adımı özenle tamamlamak, yetişme telaşı içinde gelişigüzel birçok adım atmaktan daha işe yarayabilir.', 'Speed does not compensate for losing direction. Descartes’s slower traveler suggests a different measure: completing one understood step carefully can serve you better than hurried motion without a route.', ['courage', 'patience', 'action']],
    ['II: rebuilding one’s own opinions rather than reforming the whole state', 'Hayatını yeniden düşünmek, çevrendeki her düzeni bir anda değiştirmeyi gerektirmez. Önce kendi kabullerinin yapısına bak; kişisel sorumluluğun içindeki bir düzeltme, taşıyamayacağın büyüklükte bir dönüşümden daha sağlam başlayabilir.', 'Reconsidering your life need not begin with remaking every surrounding institution. Examine the structure of your own assumptions; a change within your responsibility can provide a sounder beginning.', ['self', 'responsibility', 'change']],
    ['II: second rule, dividing difficulties', 'Bir güçlük gözünde büyüdüğünde, hepsini aynı anda çözmeye çalışma. Onu gerçekten ele alınabilecek parçalara ayır; bugün yalnız bir parçaya başlamak, korksan da hareket edebileceğin somut bir başlangıç oluşturabilir.', 'When a difficulty feels too large, separate it into parts you can actually address. Beginning with one part today can create a concrete way to move while fear is still present.', ['fear', 'courage', 'action']],
    ['II: third rule, proceeding from the simple to the complex', 'Öğrenirken en karmaşık noktadan başlamak zorunda değilsin. Önce anlayabildiğin temel ilişkiyi kur, sonra üstüne yenisini ekle; zihninin basamaklara ihtiyaç duyması, düşündüğün hedefe layık olmadığın anlamına gelmez.', 'You need not begin learning at its most complicated point. Establish a simple relationship you understand and add to it; needing steps does not make the aim unworthy of you.', ['confidence', 'learning', 'patience']],
    ['II: fourth rule, complete review and enumeration', 'Bir işi bitirdiğinde geriye dönüp kontrol etmek, kendine güvensizlik sayılmak zorunda değildir. Atladığın bir bağlantıyı aramak, emeğine gösterdiğin özenin parçasıdır; güven bazen son bir dikkatli bakışla güçlenir.', 'Reviewing completed work need not express distrust in yourself. Looking for an omitted connection is a form of care for your effort; confidence can grow through a final attentive check.', ['confidence', 'attention', 'integrity']],
    ['III: provisional morality and the temporary lodging metaphor', 'Bütün sorularını çözmeden de günlük hayatını sürdürecek bir düzene ihtiyacın olabilir. Evi yeniden kurarken geçici barınak bulmak gibi, bazı ilkeler arayışın tamamlanana kadar sana yaşanabilir bir zemin sağlayabilir.', 'You may need a way to live before every question is settled. Like finding shelter while rebuilding a house, provisional principles can provide a livable ground during an unfinished inquiry.', ['uncertainty', 'self', 'stability']],
    ['III: second maxim, the traveler lost in a forest', 'Yönünü tam bilmediğinde sürekli karar değiştirmek seni aynı yerde tutabilir. Yeterince düşündüğün makul bir yolu bir süre dene; küçük belirsizlikler yüzünden her adımı geri almak zorunda değilsin.', 'Changing direction at every uncertainty can keep you in place. Give a reasonably considered route a fair attempt instead of withdrawing each step because complete assurance has not arrived.', ['fear', 'courage', 'will']],
    ['IV: thinking and the recognition of existence', 'Kendin hakkında pek çok şeyden kuşku duysan bile, bu sorgulamanın yaşandığı gerçeğine dikkat edebilirsin. Descartes’ın düşünceden başlayan arayışı, hazır bir kimlik bulmadan da varoluşunu ciddiye alabileceğin bir nokta açar.', 'Even when much about yourself feels uncertain, notice the reality of the questioning taking place. Descartes begins there, opening a point from which existence matters before a settled identity is available.', ['self', 'existence', 'identity']],
    ['VI: knowledge useful in the conduct of life', 'Öğrendiğin şeyin değerini yalnız ne kadar etkileyici anlatıldığıyla ölçme. Hayatın gerçek bir ihtiyacına dokunup dokunmadığını da sor; küçük ama kullanılabilir bir anlayış, bugün birine yardım etmenin başlangıcı olabilir.', 'Knowledge can be assessed by its contribution to lived needs as well as its presentation. A modest, usable understanding may be enough to begin helping someone today.', ['purpose', 'action', 'knowledge']],
  ]),
  ...readings('montaigne', 'Michel de Montaigne', 'Michel de Montaigne', 'Essays (Cotton–Hazlitt, 1877)', 'Denemeler (Cotton–Hazlitt, 1877)', 'https://www.gutenberg.org/files/3600/3600-h/3600-h.htm', [
    ['III.2, Of Repentance: depicting passage rather than fixed being', 'Kendini anlatırken bitmiş bir heykeli tarif etmek zorunda değilsin. Montaigne değişen anları kaydeder; sen de bugünkü düşünceni dürüstçe söyleyebilir, yarın farklı düşündüğünde önceki bütün benliğini sahte ilan etmeyebilirsin.', 'Describing yourself need not mean presenting a finished statue. Montaigne records a life in passage; you can speak honestly today without making every later change a verdict against your former self.', ['self', 'identity', 'change']],
    ['III.2, Of Repentance: an ordinary life as a subject of examination', 'Hayatının düşünülmeye değer olması için olağanüstü bir hikâyeye dönüşmesi gerekmez. Sıradan seçimlerinde insan olmanın soruları zaten vardır; kendini incelemek, yalnız ünlü veya büyük işler yapan insanlara ayrılmış bir uğraş değildir.', 'Your life need not become an extraordinary story to deserve reflection. Ordinary choices already contain human questions; examining a life is not a privilege reserved for the celebrated.', ['self', 'existence', 'dignity']],
    ['III.8, Of the Art of Conference: welcoming contradiction in conversation', 'Konuşurken karşı çıkılmasını, kişiliğine açılmış bir dava gibi görmeden dinlemeyi dene. Bir fikrinin sınanması sana düşünceni genişletme fırsatı verebilir; her sohbetten galip çıkmak, her sohbetten bir şey öğrenmek değildir.', 'Try hearing disagreement without turning it into a trial of your worth. A challenged idea can enlarge thought; winning an exchange is not the same as learning from it.', ['ego', 'conversation', 'learning']],
    ['III.8, Of the Art of Conference: the manner of reasoning', 'Bir tartışmada yalnız ulaşılan sonuca bakma; düşüncenin oraya nasıl gittiğini de izle. Şans eseri doğru söylemekle gerekçeli konuşmak ayrıdır; kendi sözünü de aynı dikkatle tartmak, sohbeti daha dürüst kılabilir.', 'In discussion, notice the route of reasoning as well as the conclusion. Being right by chance differs from making a sound case; apply that attention to your own words too.', ['ego', 'reason', 'honesty']],
    ['III.10, Of Managing the Will: the mayor and Montaigne as distinct roles', 'Üstlendiğin görev önemli olabilir, fakat benliğinin tamamı o görev değildir. Montaigne’in belediye başkanlığıyla kendisini ayırması gibi, sorumluluğunu yerine getirirken unvanının dışında kalan hayatını da tanımaya devam edebilirsin.', 'A role can matter without becoming your entire identity. Montaigne distinguishes himself from his mayoral office; fulfill a responsibility while continuing to recognize the person whose life extends beyond it.', ['ego', 'self', 'identity']],
    ['I.26, Of the Education of Children: digesting rather than repeating learning', 'Okuduğun bir düşünceyi yalnız tekrar edebildiğinde öğrenmenin işi bitmiş olmaz. Onu kendi örneğinle anlatmayı dene; başkasından aldığın bilgiyi sindirmek, zihninde gerçekten kullanabileceğin bir anlayışa dönüşmesine yardım eder.', 'Repeating an idea is not the whole work of learning it. Try explaining it through an example of your own; borrowed knowledge needs to be digested before it becomes usable understanding.', ['self', 'learning', 'practice']],
    ['I.31, Of Cannibals: judging unfamiliar customs by one’s own habits', 'Sana yabancı gelen bir yaşamı hemen aşağı bir yere koyma. Alışkanlığın, tarafsız bir ölçü gibi konuşuyor olabilir; kendi çevreni de sorgulayabilmek, farklı insanları anlamaya daha adil bir yerden başlamanı sağlar.', 'Unfamiliar ways of living need not be ranked beneath your own. Habit can speak as though it were a neutral measure; examining your own setting makes a fairer encounter possible.', ['ego', 'difference', 'humility']],
    ['II.6, Use Makes Perfect: attending closely to one’s own experience', 'Kendine dair bir deneyimi anlatırken yalnız başkalarının senden beklediği görüntüyü korumaya çalışma. Montaigne’in kendini gözlemleyen anlatısını düşün; kırılganlığını saklamadan tarif etmek de kendin hakkında daha gerçek bir bilgiye kapı açabilir.', 'An account of your experience need not protect only the image others expect. Montaigne observes himself closely; describing vulnerability honestly can become a source of more truthful self-knowledge.', ['self', 'vulnerability', 'courage']],
    ['II.10, Of Books: changing a book and returning with fresh attention', 'Bir kitabın içinde tıkandığında, kendine hemen yetersiz damgası vurma. Montaigne bazen başka bir kitaba geçer; okumayla ilişkin, her sayfayı aynı inatla zorlamadan da merakını canlı tutan bir yol bulabilir.', 'Being stuck in a book need not become a judgment of your ability. Montaigne sometimes changes books; a living relationship with reading can leave room for another route and renewed interest.', ['self', 'curiosity', 'flexibility']],
    ['III.13, Of Experience: joining the mind to the enjoyment of living', 'Güzel bir an yaşarken zihnin yalnız onu değerlendiren bir seyirci olmak zorunda değil. Yaptığın şeye katılmayı dene; yaşamın değerini düşünmek, bazen onun sıradan bir sevincini gerçekten yaşamaya yer açmaktır.', 'During a welcome moment, your mind need not remain only an evaluating spectator. Participate in what you are doing; reflection on life can include allowing an ordinary pleasure to be fully lived.', ['self', 'presence', 'joy']],
  ]),
  ...readings('boethius', 'Boethius', 'Boethius', 'The Consolation of Philosophy (James, 1897)', 'Felsefenin Tesellisi (James, 1897)', 'https://www.gutenberg.org/files/14328/14328-h/14328-h.htm', [
    ['II.1: the changing character of Fortune', 'Değişken bir koşuldan değişmez güvence beklemek, benliğini sürekli tedirgin edebilir. Boethius’un talih sorgulamasını düşün; hayatındaki hangi desteğin kalıcı olmadığını görmek, bugün dayanabileceğin başka kaynakları aramana da yardım edebilir.', 'Expecting permanent assurance from a changing circumstance can keep you unsettled. Boethius questions Fortune’s promises; noticing what is unstable may help you look for other sources of support.', ['self', 'uncertainty', 'resilience']],
    ['II.3: remembering earlier happiness without demanding its permanence', 'Güzel bir dönemin bitmesi, o dönemde yaşadığın iyiliği hiç olmamış yapmaz. Geçmişi yalnız kaybın penceresinden okumadan, sana gerçekten verilmiş olanı da hatırlayabilirsin; hatıra, bugünün acısını inkâr etmek zorunda değildir.', 'The end of a good period does not make its goodness unreal. Remembering what you received can coexist with present pain, without asking memory to deny what has been lost.', ['self', 'memory', 'gratitude']],
    ['II.4: surviving bonds amid the loss of public fortune', 'Bir kayıp hayatının ortasına yerleştiğinde, çevresindeki her şey görünmezleşebilir. Acını küçültmeden, yanında kalmış bir bağı da fark etmeyi dene; tek bir ilişkinin varlığı bile hayatının bütününün yok olmadığını hatırlatabilir.', 'A loss can occupy the center until everything around it disappears from view. Without minimizing pain, notice a bond that remains; one relationship can remind you that the whole of life is not gone.', ['self', 'connection', 'hope']],
    ['II.5: possessions and adornments cannot supply a person’s own worth', 'Sahip olduğun şeyler güzel olabilir; fakat onların güzelliği, senin insanlık değerini üretmez. Benliğini yalnız eşyalarınla anlatmadığında, bir şey kaybetmenin neden bütün değerini kaybetmek anlamına gelmediğini daha açık görebilirsin.', 'Possessions may be beautiful without being the source of your worth. When identity is not described only through belongings, losing a thing need not mean losing everything that makes you valuable.', ['ego', 'self', 'dignity']],
    ['II.6: offices do not create virtue in their holders', 'Bir unvanın sana saygı getirmesi, onun karakterini senin yerine kurduğu anlamına gelmez. Görevin ne kadar görünür olursa olsun, adaletin ve ölçün yine günlük kararlarında ortaya çıkar; makam davranışın sorumluluğunu kaldırmaz.', 'A title may bring recognition, but it cannot form your character for you. However visible the role, fairness and restraint still have to appear in the decisions you make.', ['ego', 'character', 'responsibility']],
    ['II.7: fame measured against the world and time', 'Adının ne kadar duyulduğu, yaşamının bütün değerini ölçen tek terazi değildir. Boethius’un şöhreti geniş zaman içinde düşünmesini hatırla; görülme isteğinin yanında, kimse bilmeden önem taşıyan uğraşlarına da yer aç.', 'The reach of your name is not the only measure of a life. Boethius places fame against a wider horizon; make room for pursuits whose importance does not depend on being widely known.', ['ego', 'meaning', 'recognition']],
    ['II.8: adverse fortune reveals the quality of friendship', 'Koşullar değiştiğinde yanında kimin kaldığını görmek, ilişkilerinin niteliğini daha açık gösterebilir. Bu fark ediş kaybı iyi ilan etmez; yalnız, zor zamanda belli olan içten bir bağa daha bilinçli değer vermeni sağlayabilir.', 'Changed circumstances may reveal who remains beside you. This does not make loss good; it can help you value more consciously a sincere relationship that becomes visible in difficulty.', ['friendship', 'trust', 'meaning']],
    ['III.2: different pursuits aim at happiness', 'İnsanlar mutluluğu farklı şeylerde ararken, sen de peşinden koştuğun şeyin hangi ihtiyaca cevap vermesini beklediğini sor. Amaçla aracı ayırmak, gerçekten istediğin hayatı yalnız bir başarı işaretine indirgememeni kolaylaştırabilir.', 'When people seek happiness through different pursuits, ask what need you expect your own aim to answer. Distinguishing a means from an end can keep a life from shrinking to one sign of success.', ['self', 'purpose', 'meaning']],
    ['III.3: wealth and the continuing experience of need', 'Daha fazlasını elde etmek, her zaman yeterlilik duygusu getirmeyebilir. Bir hedef koyarken ne zaman yeter diyeceğini de düşün; eksiklik hissinin sürekli büyüdüğü bir yarışta benliğinin bütün enerjisini tüketmek zorunda değilsin.', 'Acquiring more does not always create a sense of enough. When setting an aim, consider what sufficiency would mean, so the pursuit does not absorb your whole life through endlessly renewed need.', ['ego', 'desire', 'balance']],
    ['IV.4: wrongdoing, punishment and the rejection of hatred', 'Bir haksızlığın düzelmesini istemekle öfkenin hayatını yönetmesini istemek aynı şey değildir. Boethius’un adalet tartışması gibi, yapılan yanlışı ciddiye alırken kendi tutumunun da hangi insana dönüşmene hizmet ettiğini düşün.', 'Wanting a wrong to be corrected differs from wanting anger to govern your life. Take the injustice seriously while considering what your own response is making of you.', ['self', 'justice', 'will']],
  ]),
];
